mapper.select:
SELECT device,
       SUM(cnt) AS count
FROM t_link_device_stats
WHERE full_short_url = #{fullShortUrl}
  AND gid = #{gid}
  AND date BETWEEN #{startDate} AND #{endDate}
  AND del_flag = 0
GROUP BY full_short_url, gid, device;

SELECT device,
       SUM(cnt) AS cnt
FROM t_link_device_stats
WHERE gid = #{gid}
  AND date BETWEEN #{startDate} and #{endDate}
GROUP BY gid, device;
